    requested: &BTreeMap<String, String>,
    granted: &BTreeMap<String, String>,
) -> Vec<String> {
    requested
        .iter()
        .filter(|(scope, level)| {
            !level.eq_ignore_ascii_case("none")
                && !ACTIONS_ONLY_SCOPES.contains(&scope.as_str())
                && granted
                    .get(&scope.replace('-', "_"))
                    .is_none_or(|granted| permission_rank(level) > permission_rank(granted))
