const PROBED_PERMISSIONS: [(&str, &str); 4] = [
…
    ("issues", "read"),
];

/// Probe what a credential can actually read on a repository, for
/// `preloop setup` and `preloop doctor`.
///
/// Returns the permission pairs that WORK (e.g. `contents: read`,
/// `pull-requests: read`). A credential that cannot read the repo at all is
/// an error naming the status GitHub returned; individually missing
/// permissions simply don't appear in the list.
pub async fn verify_repo_access_with_token(
    token: &str,
    repo: &str,
) -> anyhow::Result<Vec<(String, String)>> {
    verify_repo_access_at(&api_base(), token, repo).await
}

/// [`verify_repo_access_with_token`] against an explicit API base.
async fn verify_repo_access_at(
    api_base: &str,
    token: &str,
    repo: &str,
) -> anyhow::Result<Vec<(String, String)>> {
    let (owner, name) = split_repository(repo)?;
    let client = reqwest::Client::builder()
        .user_agent("preloop-doctor")
        .build()
        .context("building GitHub API client")?;
    let base = format!("{api_base}/repos/{owner}/{name}");
    // contents: read is the baseline — without it nothing else matters.
    let resp = client
        .get(&base)
        .bearer_auth(token)
        .send()
        .await
        .with_context(|| format!("probing {repo}"))?;
    let status = resp.status();
    if !status.is_success() {
        let body = resp.text().await.unwrap_or_default();
        anyhow::bail!(
            "credential cannot read {repo}: GitHub returned {}: {}",
            status,
            body.chars().take(240).collect::<String>()
        );
    }
    let mut granted = vec![("contents".to_owned(), "read".to_owned())];
    for (permission, path) in [
        ("pull-requests", "pulls?state=open&per_page=1"),
        ("actions", "actions/workflows?per_page=1"),
        ("issues", "issues?state=open&per_page=1"),
    ] {
        let url = format!("{base}/{path}");
        match client.get(&url).bearer_auth(token).send().await {
            Ok(resp) if resp.status().is_success() => {
                granted.push((permission.to_owned(), "read".to_owned()));
            }
            // 401/403 are the credential's honest answer: the permission is
            // not granted. Everything else (transport failure, 5xx, 404)
            // says nothing about the permission and must not be reported as
            // a denial — a transient GitHub hiccup would otherwise make the
            // doctor claim the App/PAT is missing a scope it actually has.
            Ok(resp)
                if resp.status() == reqwest::StatusCode::UNAUTHORIZED
                    || resp.status() == reqwest::StatusCode::FORBIDDEN => {}
            Ok(resp) => {
                bail!(
                    "cannot verify {permission} read access on {repo}: GitHub returned {}",
                    resp.status()
                )
            }
            Err(error) => {
                return Err(error)
                    .with_context(|| format!("probing {permission} read access on {repo}"))
            }
        }
    }
    Ok(granted)
}

/// Verify a GitHub App configuration by minting a scoped installation token
/// for `repo` and probing it.
pub async fn verify_app_config(
    app_id: &str,
    pem: &str,
    repo: &str,
) -> anyhow::Result<Vec<(String, String)>> {
    verify_app_config_at(&api_base(), app_id, pem, repo).await
}

/// [`verify_app_config`] against an explicit API base.
async fn verify_app_config_at(
    api_base: &str,
    app_id: &str,
    pem: &str,
    repo: &str,
) -> anyhow::Result<Vec<(String, String)>> {
    let creds = credentials_for(app_id, pem)?;
    // The verification token must request every permission the probe reports
    // on. GitHub narrows an installation token to the intersection of what is
    // requested and what the installation was granted, so a contents-only
    // token would fail the pull-requests, actions and issues probes no matter
    // what the installation actually grants — the doctor would be reporting
    // the scope of its own temporary token instead of the installation's.
    let probed: BTreeMap<String, String> = PROBED_PERMISSIONS
        .iter()
        .map(|(scope, level)| ((*scope).to_owned(), (*level).to_owned()))
        .collect();
    let (token, degraded) = match get_or_mint_token_at(api_base, &creds, repo, &probed).await {
        Ok(token) => (token, false),
        Err(error) => {
            // A correctly configured App must never hard-fail the doctor just
            // because the wider mint was refused: fall back to the baseline
            // token and mark the result so the report says so out loud.
            debug!(
                repository = repo,
                error = format!("{error:#}"),
                "minting a probe token with the full permission set failed; falling back to \
                 contents-only"
            );
            let baseline = BTreeMap::from([("contents".to_owned(), "read".to_owned())]);
            let token = get_or_mint_token_at(api_base, &creds, repo, &baseline)
                .await
                .with_context(|| format!("minting an installation token for {repo}"))?;
            (token, true)
        }
    };
    let mut granted = verify_repo_access_at(api_base, &token, repo).await?;
    if degraded {
        granted.push((
            "probe".to_owned(),
            "degraded (contents-only token; other permissions unverified)".to_owned(),
        ));
    }
    Ok(granted)
}

/// Point an existing App's webhook at `url` with `secret`.
///
/// Creating a second App just to change a URL is the alternative, and it
/// leaves the first one installed and minting tokens — so a deployment that
/// starts on loopback and later gains a public address updates the App it
/// already has. Authenticates with the App JWT, the only credential
/// `/app/hook/config` accepts.
///
/// GitHub exposes no `active` flag on this endpoint: an App created with
/// `hook_attributes.active = false` keeps that checkbox until it is flipped
/// in the App's settings. The caller is expected to say so.
pub async fn set_app_webhook_config(
    app_id: &str,
    pem: &str,
    url: &str,
    secret: &str,
) -> anyhow::Result<()> {
    set_app_webhook_config_at(&api_base(), app_id, pem, url, secret).await
}

/// [`set_app_webhook_config`] against an explicit API base.
async fn set_app_webhook_config_at(
    api_base: &str,
    app_id: &str,
    pem: &str,
    url: &str,
    secret: &str,
) -> anyhow::Result<()> {
    let creds = credentials_for(app_id, pem)?;
    let app_jwt = sign_app_jwt(&creds.app_id, &creds.private_key)?;
    let response = crate::shared_http::CLIENT
        .patch(format!("{api_base}/app/hook/config"))
        .bearer_auth(&app_jwt)
        .header("Accept", "application/vnd.github+json")
        .header("User-Agent", "preloop")
        .json(&serde_json::json!({
            "url": url,
            "content_type": "json",
            "secret": secret,
            "insecure_ssl": "0",
        }))
        .send()
        .await
        .context("calling GitHub to update the App webhook configuration")?;
    let status = response.status();
    if status.is_success() {
        // GitHub cannot change an App's event subscription through the API
        // (only `url`, `content_type`, and `secret` are mutable here), so
        // read the subscription back and warn when the trigger events preloop
        // turns into runs are missing — the operator has to tick them in the
        // App settings UI.
        match read_app_events_at(api_base, app_id, &creds.private_key).await {
            Ok(events) => warn_missing_trigger_events(app_id, &events),
            Err(error) => warn!(
                app_id,
                ?error,
                "could not read back the App's event subscription after updating \
                 the webhook configuration"
            ),
        }
        return Ok(());
    }
    let body = response.text().await.unwrap_or_default();
    anyhow::bail!(
        "GitHub refused the webhook update ({status}): {}",
        body.trim()
    )
}

/// Webhook events a preloop GitHub App must subscribe to for the full CI
/// surface to work (D7). These are the Tier A + trigger events the adapters
/// turn into runs; an App not subscribed to one of them will never deliver
/// that webhook to preloop no matter how the workflow YAML is written.
pub(crate) fn required_trigger_events() -> &'static [&'static str] {
    &[
        "push",
        "pull_request",
        "pull_request_target",
        "pull_request_review",
        "workflow_dispatch",
        "workflow_run",
        "repository_dispatch",
        "issue_comment",
        "issues",
        "check_run",
        "check_suite",
        "create",
        "delete",
        "release",
    ]
}

/// The required trigger events `subscribed` is missing, in canonical order.
pub(crate) fn missing_trigger_events(subscribed: &[String]) -> Vec<String> {
    required_trigger_events()
        .iter()
        .filter(|event| !subscribed.iter().any(|have| have == *event))
        .map(|event| (*event).to_owned())
        .collect()
}

/// Loudly warn when an App's subscribed events do not cover the trigger set.
///
/// GitHub cannot change an App's event subscription through the API — only
/// the App settings UI can — so this is a warning with exact instructions,
/// not an attempt to fix the App.
pub(crate) fn warn_missing_trigger_events(app_id: &str, subscribed: &[String]) {
    let missing = missing_trigger_events(subscribed);
    if missing.is_empty() {
        return;
    }
    tracing::warn!(
        app_id,
        missing = %missing.join(", "),
        "GitHub App {app_id} is not subscribed to webhook events preloop needs \
         (missing: {}). GitHub will never deliver those events to preloop. Open \
         the App's settings (https://github.com/settings/apps/{app_id}) → Webhooks \
         → Edit → and tick the missing events.",
        missing.join(", ")
    );
}

/// Read the webhook events an App is subscribed to via `GET /app`.
///
/// Authenticates with the App JWT — the only credential `/app` accepts.
/// Returns the `events` array; a transport or auth failure is an error so
/// the caller decides how loudly to fail (fail closed, never pretend the
/// subscription is fine when it could not be read).
pub(crate) async fn read_app_events_at(
    api_base: &str,
    app_id: &str,
    private_key: &rsa::RsaPrivateKey,
) -> anyhow::Result<Vec<String>> {
    let app_jwt = sign_app_jwt(app_id, private_key)?;
    let response = CLIENT
        .get(format!("{api_base}/app"))
        .header("User-Agent", "preloop")
        .header("Authorization", format!("Bearer {app_jwt}"))
        .header("Accept", "application/vnd.github+json")
        .send()
        .await
        .with_context(|| format!("GET {api_base}/app"))?;
    let status = response.status();
    let body = response.text().await.unwrap_or_default();
    if !status.is_success() {
        bail!(
            "GET /app failed with {status}: {}",
            body.chars().take(1024).collect::<String>()
        );
    }
    let payload: serde_json::Value =
        serde_json::from_str(&body).with_context(|| "GET /app returned a non-JSON body")?;
    let events = payload
        .get("events")
        .and_then(serde_json::Value::as_array)
        .map(|events| {
            events
                .iter()
                .filter_map(|event| event.as_str().map(str::to_owned))
                .collect::<Vec<_>>()
        })
        .unwrap_or_default();
    Ok(events)
}

/// Build credentials from raw config pieces (no environment involved).
fn credentials_for(app_id: &str, pem: &str) -> anyhow::Result<GitHubAppCredentials> {
    let private_key = parse_private_key(pem).context("parsing the GitHub App private key")?;
    Ok(GitHubAppCredentials {
        app_id: app_id.to_owned(),
        private_key,
        mint_failure: MintFailurePolicy::LocalJwt,
        pat_fallback: None,
        installation_cache: Arc::new(RwLock::new(HashMap::new())),
        mint_ledger: Arc::new(MintLedger::default()),
        webhook_secret: None,
        installation_id: None,
    })
}

