/// Paginated `GET /installation/repositories` full-name list.
async fn fetch_installation_repositories(
    api_base: &str,
    token: &str,
) -> anyhow::Result<Vec<String>> {
    let mut repositories = Vec::new();
    // `total_count` (first response) is the authoritative stop point — an
    // installation with more than 1,000 repositories must not be truncated —
    // and a short page is the belt for a response that lies. Pages past the
    // end return an empty array, so the loop always terminates.
    let mut total_count: Option<usize> = None;
    for page in 1u32.. {
        let body = fetch_json(
            &format!("{api_base}/installation/repositories?per_page=100&page={page}"),
            token,
        )
        .await
        .with_context(|| format!("GET /installation/repositories (page {page}) failed"))?;
        if total_count.is_none() {
            total_count = body
                .get("total_count")
                .and_then(serde_json::Value::as_u64)
                .map(|count| count as usize);
        }
        let batch = body
            .get("repositories")
            .and_then(serde_json::Value::as_array)
            .cloned()
            .unwrap_or_default();
        let page_len = batch.len();
        repositories.extend(batch.into_iter().filter_map(|repository| {
            repository
                .get("full_name")
                .and_then(serde_json::Value::as_str)
                .map(str::to_owned)
        }));
        if page_len < 100 {
            break;
        }
        if total_count.is_some_and(|total| repositories.len() >= total) {
            break;
        }
    }
    Ok(repositories)
}
